def squares_text(limit):
    lines = []
    for n in range(limit + 1):
        lines.append(f'{n} x {n} = {n * n}')
    return lines

def even_odd_sums(limit):
    evens = 0
    odds = 0
    for n in range(limit + 1):
        if n % 2 == 0:
            evens += n
        else:
            odds += n
    return evens, odds

